function captureYnteligenciaAttribution(){

  const params=
    new URLSearchParams(
      window.location.search
    );

  const keys=[
    "gclid",
    "gbraid",
    "wbraid",
    "utm_source",
    "utm_medium",
    "utm_campaign",
    "utm_content",
    "utm_term"
  ];

  const attribution={};

  keys.forEach(key=>{

    const incoming=
      clean(
        params.get(key)
      );

    if(incoming){

      safeStorageSet(
        `ynteligencia_${key}`,
        incoming
      );

      attribution[key]=incoming;

    }else{

      attribution[key]=
        safeStorageGet(
          `ynteligencia_${key}`
        ) || "";
    }

  });

  return attribution;
}

function inferYnteligenciaCurrentTouch(){
  const params=
    new URLSearchParams(
      window.location.search
    );

  const current={
    gclid:
      clean(params.get("gclid")),

    gbraid:
      clean(params.get("gbraid")),

    wbraid:
      clean(params.get("wbraid")),

    utm_source:
      clean(params.get("utm_source")),

    utm_medium:
      clean(params.get("utm_medium")),

    utm_campaign:
      clean(params.get("utm_campaign")),

    utm_content:
      clean(params.get("utm_content")),

    utm_term:
      clean(params.get("utm_term")),

    referrer:
      document.referrer || "",

    landing_page:
      window.location.href,

    captured_at:
      new Date()
        .toISOString(),

    source:
      "",

    medium:
      "",

    campaign:
      ""
  };

  const hasPaidClick=
    Boolean(
      current.gclid ||
      current.gbraid ||
      current.wbraid
    );

  if(
    current.utm_source ||
    current.utm_medium ||
    current.utm_campaign
  ){
    current.source=
      current.utm_source ||
      (
        hasPaidClick
          ? "google"
          : "utm"
      );

    current.medium=
      current.utm_medium ||
      (
        hasPaidClick
          ? "cpc"
          : "unknown"
      );

    current.campaign=
      current.utm_campaign ||
      "";

    return current;
  }

  if(hasPaidClick){
    current.source=
      "google";

    current.medium=
      "cpc";

    return current;
  }

  let refHost="";

  try{
    refHost=
      document.referrer
        ? new URL(
            document.referrer
          ).hostname
            .toLowerCase()
        : "";
  }catch{
    refHost="";
  }

  const ownHost=
    window.location.hostname
      .toLowerCase();

  if(
    !refHost ||
    refHost === ownHost
  ){
    current.source=
      "direct";

    current.medium=
      "(none)";

    return current;
  }

  if(
    /(^|\.)google\./.test(refHost) ||
    refHost.includes("google.")
  ){
    current.source=
      "google";

    current.medium=
      "organic";

    return current;
  }

  if(
    refHost.includes("bing.") ||
    refHost.includes("yahoo.") ||
    refHost.includes("duckduckgo.")
  ){
    current.source=
      refHost.split(".")[0] ||
      refHost;

    current.medium=
      "organic";

    return current;
  }

  current.source=
    refHost;

  current.medium=
    "referral";

  return current;
}

function resolveYnteligenciaTouches(){
  const firstKey=
    "ynteligencia_first_touch_v2";

  const previousTouchKey=
    "ynteligencia_previous_session_touch_v2";

  const current=
    inferYnteligenciaCurrentTouch();

  let first=
    safeStorageGetJSON(
      firstKey
    );

  if(!first){
    /*
      Se já existia atribuição legada, aproveitamos como first touch.
      Isso preserva usuários que entraram antes desta atualização.
    */
    const legacy=
      YNTELIGENCIA_ATTRIBUTION ||
      {};

    const hasLegacy=
      Boolean(
        legacy.gclid ||
        legacy.gbraid ||
        legacy.wbraid ||
        legacy.utm_source ||
        legacy.utm_medium ||
        legacy.utm_campaign
      );

    first=
      hasLegacy
        ? {
            ...legacy,

            source:
              legacy.utm_source ||
              (
                legacy.gclid ||
                legacy.gbraid ||
                legacy.wbraid
                  ? "google"
                  : ""
              ),

            medium:
              legacy.utm_medium ||
              (
                legacy.gclid ||
                legacy.gbraid ||
                legacy.wbraid
                  ? "cpc"
                  : ""
              ),

            campaign:
              legacy.utm_campaign ||
              "",

            captured_at:
              safeStorageGet(
                "ynteligencia_first_seen_at"
              ) ||
              new Date()
                .toISOString(),

            migrated_from_legacy:
              true
          }
        : {
            ...current
          };

    safeStorageSetJSON(
      firstKey,
      first
    );
  }

  if(
    !safeStorageGet(
      "ynteligencia_first_seen_at"
    )
  ){
    safeStorageSet(
      "ynteligencia_first_seen_at",
      first.captured_at ||
      new Date()
        .toISOString()
    );
  }

  const previousSessionTouch=
    safeStorageGetJSON(
      previousTouchKey
    );

  /*
    Grava current touch somente uma vez por session_id.
    Reload da mesma sessão não deve sobrescrever a origem da visita.
  */
  const sessionTouchKey=
    `ynteligencia_session_touch_${YNTELIGENCIA_SESSION_ID}`;

  let sessionTouch=
    safeStorageGetJSON(
      sessionTouchKey
    );

  if(!sessionTouch){
    sessionTouch={
      ...current,

      session_id:
        YNTELIGENCIA_SESSION_ID,

      session_number:
        YNTELIGENCIA_SESSION
          .session_number
    };

    safeStorageSetJSON(
      sessionTouchKey,
      sessionTouch
    );

    if(
      previousSessionTouch &&
      previousSessionTouch.session_id !==
        YNTELIGENCIA_SESSION_ID
    ){
      safeStorageSetJSON(
        "ynteligencia_last_completed_touch_v2",
        previousSessionTouch
      );
    }

    safeStorageSetJSON(
      previousTouchKey,
      sessionTouch
    );
  }

  const previous=
    safeStorageGetJSON(
      "ynteligencia_last_completed_touch_v2"
    );

  const sameCampaignAsPrevious=
    Boolean(
      previous &&
      sessionTouch &&
      clean(previous.campaign) &&
      clean(sessionTouch.campaign) &&
      norm(previous.campaign) ===
        norm(sessionTouch.campaign)
    );

  const sameSourceAsPrevious=
    Boolean(
      previous &&
      sessionTouch &&
      clean(previous.source) &&
      clean(sessionTouch.source) &&
      norm(previous.source) ===
        norm(sessionTouch.source) &&
      norm(previous.medium) ===
        norm(sessionTouch.medium)
    );

  return {
    first_touch:
      first,

    current_touch:
      sessionTouch,

    previous_touch:
      previous,

    same_campaign_as_previous:
      sameCampaignAsPrevious,

    same_source_as_previous:
      sameSourceAsPrevious
  };
}

async function supabaseTrack(
  eventType,
  metadata={}
){

  try{

    const response=await fetch(
      `${SUPABASE_URL}/rest/v1/events`,
      {
        method:"POST",

        headers:{
          "apikey":
            SUPABASE_PUBLISHABLE_KEY,

          "Content-Type":
            "application/json",

          "Prefer":
            "return=minimal"
        },

        body:JSON.stringify((()=>{

          /*
            EVENTOS DO APP · CONTEXTO PADRÃO
            --------------------------------
            A tabela events possui property_id no nível principal.
            Antes vários eventos guardavam o imóvel somente dentro
            de metadata, deixando a coluna property_id como NULL.
          */
          const propertyIdCandidate=
            clean(
              metadata?.property_uuid ||
              metadata?.property?.db_id ||
              metadata?.property_id ||
              metadata?.property?.id ||
              ""
            );

          /*
            public.events.property_id é UUID.
            IDs como "orulo:51327:78637" continuam no metadata,
            mas NUNCA são enviados para a coluna UUID.
          */
          const isUuid=
            /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
              .test(propertyIdCandidate);

          const resolvedPropertyId=
            isUuid
              ? propertyIdCandidate
              : "";

          const params=
            new URLSearchParams(
              window.location.search
            );

          const campaignIntent={
            mode:
              params.get("modo") || "",

            neighborhood:
              params.get("bairro") ||
              params.get("busca") ||
              (
                typeof adIntent!=="undefined"
                  ? adIntent?.neighborhood
                  : ""
              ) ||
              "",

            region:
              params.get("regiao") ||
              "",

            bedrooms:
              Number(
                params.get("dormitorios") ||
                (
                  typeof adIntent!=="undefined"
                    ? adIntent?.bedrooms
                    : 0
                ) ||
                0
              ) || 0,

            min_price:
              Number(
                params.get("valor_min") ||
                (
                  typeof adIntent!=="undefined"
                    ? adIntent?.minPrice
                    : 0
                ) ||
                0
              ) || 0,

            max_price:
              Number(
                params.get("valor_max") ||
                (
                  typeof adIntent!=="undefined"
                    ? adIntent?.maxPrice
                    : 0
                ) ||
                0
              ) || 0,

            type:
              params.get("tipo") || "",

            city:
              params.get("cidade") ||
              (
                typeof activeCity!=="undefined"
                  ? activeCity
                  : ""
              ) ||
              "",

            state:
              params.get("estado") ||
              (
                typeof activeState!=="undefined"
                  ? activeState
                  : ""
              ) ||
              ""
          };

          touchYnteligenciaSession();

          const eventSequence=
            nextYnteligenciaEventSequence();

          const previousEvent=
            getYnteligenciaPreviousEvent();

          const currentEventForJourney={
            sequence:
              eventSequence,

            event_type:
              eventType,

            property_id:
              resolvedPropertyId || "",

            created_at:
              new Date()
                .toISOString()
          };

          setYnteligenciaPreviousEvent(
            currentEventForJourney
          );

          return {

            session_id:
              YNTELIGENCIA_SESSION_ID,

            /*
              Só enviamos quando existe.
              Para eventos gerais, fica null.
            */
            property_id:
              resolvedPropertyId || null,

            event_type:
              eventType,

            metadata:{
              ...metadata,

              page:
                location.pathname,

              search:
                location.search,

              source_mode:
                sourceMode || "usados",

              visitor_id:
                YNTELIGENCIA_VISITOR_ID,

              event_sequence:
                eventSequence,

              journey:{
                sequence:
                  eventSequence,

                previous_event_type:
                  previousEvent?.event_type ||
                  "",

                previous_property_id:
                  previousEvent?.property_id ||
                  "",

                previous_sequence:
                  Number(
                    previousEvent?.sequence
                  ) || 0
              },

              session:{
                number:
                  Number(
                    YNTELIGENCIA_SESSION
                      .session_number
                  ) || 1,

                is_returning:
                  Boolean(
                    YNTELIGENCIA_SESSION
                      .is_returning
                  ),

                started_at:
                  YNTELIGENCIA_SESSION
                    .started_at ||
                  "",

                previous_session_id:
                  YNTELIGENCIA_SESSION
                    .previous_session_id ||
                  "",

                previous_session_started_at:
                  YNTELIGENCIA_SESSION
                    .previous_session_started_at ||
                  "",

                days_since_last_visit:
                  Number.isFinite(
                    Number(
                      YNTELIGENCIA_SESSION
                        .days_since_last_visit
                    )
                  )
                    ? Number(
                        YNTELIGENCIA_SESSION
                          .days_since_last_visit
                      )
                    : null
              },

              campaign_intent:
                campaignIntent,

              /*
                Compatibilidade:
                attribution continua sendo a atribuição legada/última
                conhecida usada pela esteira atual.
              */
              attribution:{
                ...YNTELIGENCIA_ATTRIBUTION
              },

              first_touch:{
                ...YNTELIGENCIA_TOUCHES
                  .first_touch
              },

              current_touch:{
                ...YNTELIGENCIA_TOUCHES
                  .current_touch
              },

              previous_touch:
                YNTELIGENCIA_TOUCHES
                  .previous_touch
                  ? {
                      ...YNTELIGENCIA_TOUCHES
                        .previous_touch
                    }
                  : null,

              attribution_compare:{
                same_campaign_as_previous:
                  Boolean(
                    YNTELIGENCIA_TOUCHES
                      .same_campaign_as_previous
                  ),

                same_source_as_previous:
                  Boolean(
                    YNTELIGENCIA_TOUCHES
                      .same_source_as_previous
                  )
              }
            }

          };

        })())

      }
    );


    if(!response.ok){

      const detail=
        await response.text();

      console.warn(
        `Supabase ${eventType} não gravou:`,
        response.status,
        detail
      );

      return false;
    }

    return true;

  }catch(error){

    console.warn(
      `Falha Supabase ${eventType}:`,
      error
    );

    return false;
  }
}


